    13	public class OccupancyReport extends Report {
    14	    private final LocalDate date;
    15	    private final ReservationRepository reservationRepository;
    16	    private final RoomRepository roomRepository;
    17	
    18	    public OccupancyReport(LocalDate date, ReservationRepository reservationRepository,
    19	                          RoomRepository roomRepository) {
    20	        this.date = date;
    21	        this.reservationRepository = reservationRepository;
    22	        this.roomRepository = roomRepository;
    23	    }
    24	
    25	    @Override
    26	    protected String getReportName() {
    27	        return "occupancy";
    28	    }
    29	
    30	    @Override
    31	    protected String getPeriod() {
    32	        return date.format(DateTimeFormatter.ISO_LOCAL_DATE);
    33	    }
    34	
    35	    @Override
    36	    protected String buildHeaderLine() {
    37	        return "room,type,reservation,check_in,check_out";
    38	    }
    39	
    40	    @Override
    41	    protected List<String> buildDataLines() {
    42	        List<String> lines = new ArrayList<>();
    43	        List<Reservation> reservations = reservationRepository.findPaidByNight(date);
    44	
    45	        reservations.stream()
    46	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
    47	                .forEach(r -> {
    48	                    lines.add(String.format("%s,%s,%d,%s,%s",
    49	                            r.getRoomNumber(),
    50	                            getRoomType(r.getRoomNumber()),
    51	                            r.getId(),
    52	                            r.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE),
    53	                            r.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)
    54	                    ));
    55	                });
    56	
    57	        return lines;
    58	    }
    59	
    60	    @Override
    61	    protected String buildTotalLine() {
    62	        int occupiedRooms = reservationRepository.findPaidByNight(date).size();
    63	        int totalRooms = roomRepository.getTotalRooms();
    64	        return String.format("total,%d/%d", occupiedRooms, totalRooms);
    65	    }
    66	
    67	    private String getRoomType(String roomNumber) {
    68	        return roomRepository.findByNumber(roomNumber)
    69	                .map(room -> room.getType().name())
    70	                .orElse("UNKNOWN");
    71	    }
