     1	package com.pousada.report;
     2	
     3	import com.pousada.domain.RatePlan;
     4	import com.pousada.domain.Reservation;
     5	import com.pousada.repository.ReservationRepository;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Map;
    13	import java.util.stream.Collectors;
    14	
    15	public class RatePlansReport extends Report {
    16	    private final YearMonth month;
    17	    private final ReservationRepository reservationRepository;
    18	
    19	    public RatePlansReport(YearMonth month, ReservationRepository reservationRepository) {
    20	        this.month = month;
    21	        this.reservationRepository = reservationRepository;
    22	    }
    23	
    24	    @Override
    25	    protected String getReportName() {
    26	        return "rate-plans";
    27	    }
    28	
    29	    @Override
    30	    protected String getPeriod() {
    31	        return month.format(DateTimeFormatter.ofPattern("yyyy-MM"));
    32	    }
    33	
    34	    @Override
    35	    protected String buildHeaderLine() {
    36	        return "rate_plan,reservations,amount";
    37	    }
    38	
    39	    @Override
    40	    protected List<String> buildDataLines() {
    41	        List<String> lines = new ArrayList<>();
    42	        List<Reservation> monthReservations = reservationRepository.findByCheckInMonth(month);
    43	
    44	        Map<RatePlan, List<Reservation>> byPlan = monthReservations.stream()
    45	                .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
    46	                .collect(Collectors.groupingBy(Reservation::getRatePlan));
    47	
    48	        for (RatePlan plan : RatePlan.values()) {
    49	            List<Reservation> planReservations = byPlan.getOrDefault(plan, List.of());
    50	            int count = planReservations.size();
    51	            BigDecimal amount = planReservations.stream()
    52	                    .map(Reservation::getNetAmount)
    53	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
    54	
    55	            lines.add(String.format("%s,%d,%s",
    56	                    plan.name(),
    57	                    count,
    58	                    formatAmount(amount)
    59	            ));
    60	        }
    61	
    62	        return lines;
    63	    }
    64	
    65	    @Override
    66	    protected String buildTotalLine() {
    67	        List<Reservation> monthReservations = reservationRepository.findByCheckInMonth(month);
    68	
    69	        int totalCount = (int) monthReservations.stream()
    70	                .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
    71	                .count();
    72	
    73	        BigDecimal totalAmount = monthReservations.stream()
    74	                .map(Reservation::getNetAmount)
    75	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    76	
    77	        return String.format("total,%d,%s", totalCount, formatAmount(totalAmount));
    78	    }
    79	
    80	    private String formatAmount(BigDecimal amount) {
    81	        return amount.toString();
    82	    }
    83	}
