     1	package com.pousada.report;
     2	
     3	import com.pousada.domain.Reservation;
     4	import com.pousada.repository.ReservationRepository;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeFormatter;
     9	import java.util.ArrayList;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class TourismTaxReport extends Report {
    14	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    15	
    16	    private final YearMonth month;
    17	    private final ReservationRepository reservationRepository;
    18	
    19	    public TourismTaxReport(YearMonth month, ReservationRepository reservationRepository) {
    20	        this.month = month;
    21	        this.reservationRepository = reservationRepository;
    22	    }
    23	
    24	    @Override
    25	    protected String getReportName() {
    26	        return "tourism-tax";
    27	    }
    28	
    29	    @Override
    30	    protected String getPeriod() {
    31	        return month.format(DateTimeFormatter.ofPattern("yyyy-MM"));
    32	    }
    33	
    34	    @Override
    35	    protected String buildHeaderLine() {
    36	        return "reservation,room,check_in,check_out,guests,nights,tax";
    37	    }
    38	
    39	    @Override
    40	    protected List<String> buildDataLines() {
    41	        List<String> lines = new ArrayList<>();
    42	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
    43	
    44	        reservations.stream()
    45	                .filter(Reservation::isPaid)
    46	                .sorted(Comparator.comparing(Reservation::getCheckIn)
    47	                        .thenComparing(Reservation::getId))
    48	                .forEach(r -> {
    49	                    BigDecimal tax = calculateTax(r);
    50	                    lines.add(String.format("%d,%s,%s,%s,%d,%d,%s",
    51	                            r.getId(),
    52	                            r.getRoomNumber(),
    53	                            r.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE),
    54	                            r.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE),
    55	                            r.getGuests(),
    56	                            r.getNights(),
    57	                            formatAmount(tax)
    58	                    ));
    59	                });
    60	
    61	        return lines;
    62	    }
    63	
    64	    @Override
    65	    protected String buildTotalLine() {
    66	        BigDecimal total = reservationRepository.findByCheckInMonth(month).stream()
    67	                .filter(Reservation::isPaid)
    68	                .map(this::calculateTax)
    69	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    70	
    71	        return "total," + formatAmount(total);
    72	    }
    73	
    74	    private BigDecimal calculateTax(Reservation reservation) {
    75	        return TAX_PER_GUEST_PER_NIGHT
    76	                .multiply(new BigDecimal(reservation.getGuests()))
    77	                .multiply(new BigDecimal(reservation.getNights()));
    78	    }
    79	
    80	    private String formatAmount(BigDecimal amount) {
    81	        return amount.toString();
    82	    }
    83	}
