   163	        }
   164	
   165	        return false;
   166	    }
   167	
   168	    public void confirm() {
   169	        if (status != ReservationStatus.PENDING) {
   170	            throw new IllegalStateException("Only pending reservations can be confirmed");
   171	        }
   172	        this.status = ReservationStatus.CONFIRMED;
   173	        this.amountPaid = getTotal();
   174	    }
   175	
   176	    public void checkIn() {
   177	        if (status != ReservationStatus.CONFIRMED) {
   178	            throw new IllegalStateException("Only confirmed reservations can check in");
   179	        }
   180	        this.status = ReservationStatus.CHECKED_IN;
   181	    }
   182	
   183	    public void checkOut() {
   184	        if (status != ReservationStatus.CHECKED_IN) {
   185	            throw new IllegalStateException("Only checked-in reservations can check out");
   186	        }
   187	        this.status = ReservationStatus.CHECKED_OUT;
   188	    }
   189	
   190	    public void cancel() {
   191	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   192	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
   193	        }
   194	
   195	        this.status = ReservationStatus.CANCELLED;
   196	
   197	        if (ratePlan.isRefundable()) {
   198	            this.refund = amountPaid;
   199	        } else {
   200	            this.refund = BigDecimal.ZERO;
   201	        }
   202	    }
   203	
   204	    public boolean isPaid() {
   205	        return status == ReservationStatus.CONFIRMED ||
   206	               status == ReservationStatus.CHECKED_IN ||
   207	               status == ReservationStatus.CHECKED_OUT;
   208	    }
   209	
   210	    public BigDecimal getNetAmount() {
   211	        BigDecimal net = amountPaid;
   212	        if (refund != null) {
   213	            net = net.subtract(refund);
   214	        }
   215	        return net;
   216	    }
   217	}
