    84	
    85	            if (!checkOut.isAfter(checkIn)) {
    86	                throw new ValidationException("Check-out date must be after check-in date");
    87	            }
    88	
    89	            if (request.getGuests() < 1) {
    90	                throw new ValidationException("Number of guests must be at least 1");
    91	            }
    92	
    93	            Reservation reservation = reservationService.createReservation(
    94	                    request.getRoomNumber(),
    95	                    request.getGuestName(),
    96	                    request.getGuestEmail(),
    97	                    request.getGuestCpf(),
    98	                    checkIn,
    99	                    checkOut,
   100	                    request.getGuests(),
   101	                    ratePlan
   102	            );
   103	
   104	            ctx.status(201).json(new ReservationResponse(reservation));
   105	        } catch (DateTimeParseException e) {
   106	            throw new ValidationException("Invalid date format. Expected: yyyy-MM-dd");
   107	        } catch (IllegalArgumentException e) {
   108	            throw new ValidationException("Invalid rate plan. Expected: STANDARD or NON_REFUNDABLE");
   109	        }
