   112	    private void validateCreateRequest(CreateReservationRequest request) {
   113	        if (request.getRoomNumber() == null || request.getRoomNumber().isEmpty()) {
   114	            throw new ValidationException("Room number is required");
   115	        }
   116	        if (request.getGuestName() == null || request.getGuestName().isEmpty()) {
   117	            throw new ValidationException("Guest name is required");
   118	        }
   119	        if (request.getGuestEmail() == null || request.getGuestEmail().isEmpty()) {
   120	            throw new ValidationException("Guest email is required");
   121	        }
   122	        if (request.getGuestCpf() == null || request.getGuestCpf().isEmpty()) {
   123	            throw new ValidationException("Guest CPF is required");
   124	        }
   125	        if (request.getCheckIn() == null || request.getCheckIn().isEmpty()) {
   126	            throw new ValidationException("Check-in date is required");
   127	        }
   128	        if (request.getCheckOut() == null || request.getCheckOut().isEmpty()) {
   129	            throw new ValidationException("Check-out date is required");
   130	        }
   131	        if (request.getGuests() == null) {
   132	            throw new ValidationException("Number of guests is required");
   133	        }
   134	        if (request.getRatePlan() == null || request.getRatePlan().isEmpty()) {
   135	            throw new ValidationException("Rate plan is required");
   136	        }
