    68	        Reservation reservation = getReservation(id);
    69	
    70	        try {
    71	            reservation.checkIn();
    72	            return reservation;
    73	        } catch (IllegalStateException e) {
    74	            throw new OperationNotAllowedException(e.getMessage());
    75	        }
    76	    }
    77	
    78	    public Reservation checkOut(long id) {
    79	        Reservation reservation = getReservation(id);
    80	
    81	        try {
    82	            reservation.checkOut();
    83	            return reservation;
    84	        } catch (IllegalStateException e) {
    85	            throw new OperationNotAllowedException(e.getMessage());
    86	        }
    87	    }
