    22	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    23	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    24	                                        int guests, RatePlan ratePlan) {
    25	        Room room = roomRepository.findByNumber(roomNumber)
    26	                .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    27	
    28	        if (guests > room.getCapacity()) {
    29	            throw new CapacityExceededException("Room " + roomNumber + " has capacity for " +
    30	                    room.getCapacity() + " guests, but " + guests + " were requested");
    31	        }
    32	
    33	        LocalDate date = checkIn;
    34	        while (date.isBefore(checkOut)) {
    35	            if (!reservationRepository.findByRoomAndNight(roomNumber, date).isEmpty()) {
    36	                throw new RoomUnavailableException("Room " + roomNumber + " is already booked for " + date);
    37	            }
    38	            date = date.plusDays(1);
    39	        }
    40	
    41	        long id = reservationRepository.getNextId();
    42	        Reservation reservation = new Reservation(
    43	                id, roomNumber, room.getType(), guestName, guestEmail, guestCpf,
    44	                checkIn, checkOut, guests, ratePlan, room.getNightlyRate()
    45	        );
    46	
    47	        return reservationRepository.save(reservation);
    48	    }
